เข้าใจครับ สิ่งที่คุณต้องการคือการยกระดับระบบจาก "แค่หน้าเว็บกดสั่ง" ให้เป็น "ระบบจัดการออเดอร์" ที่สมบูรณ์ขึ้น โดยมีฟีเจอร์หลักคือ:
1.  **รันเลข Order No. (เช่น #01) อัตโนมัติ** และรีเซ็ตเป็น #01 ใหม่ทุกเที่ยงคืน
2.  **บันทึกข้อมูลลง Google Sheet** โดยอัตโนมัติเมื่อกดยืนยัน
3.  **ระบบหลังบ้านใน Google Sheet** (ปุ่มสถานะ, ล็อคเซลล์, ใส่รหัสผ่านแก้ไข)

เนื่องจากเว็บของคุณเป็นแบบ Frontend (React) การจะทำเรื่องพวกนี้ (รันเลข, บันทึกข้อมูล) จำเป็นต้องมี **"ตัวกลาง"** ฝั่ง Server ครับ แต่ไม่ต้องห่วง เราจะใช้ **Google Apps Script** (ฟรี และผูกกับ Sheet คุณอยู่แล้ว) มาทำหน้าที่นี้ครับ

นี่คือขั้นตอนที่คุณต้องทำ และโค้ดที่ผมแก้ไขให้ครับ

### ขั้นตอนที่ 1: ติดตั้งระบบหลังบ้าน (Google Apps Script)
**สำคัญมาก:** คุณต้องทำขั้นตอนนี้ใน Google Sheet ของคุณก่อน ไม่อย่างนั้นแอปจะบันทึกข้อมูลไม่ได้

1.  เปิด Google Sheet ข้อมูลของคุณ
2.  ไปที่เมนู **Extensions (ส่วนขยาย)** > **Apps Script**
3.  ลบโค้ดเก่าทั้งหมด แล้ววางโค้ดนี้ลงไป:

```javascript
// --- ตั้งค่ารหัสผ่านแก้ไข ---
const EDIT_PASSWORD = "198";
const SHEET_NAME = "Orders"; // ชื่อชีทที่จะเก็บออเดอร์ (ต้องสร้างชีทชื่อนี้)

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName(SHEET_NAME);

    // ถ้าไม่มีชีทชื่อ Orders ให้สร้างใหม่และทำหัวตาราง
    if (!sheet) {
      sheet = ss.insertSheet(SHEET_NAME);
      sheet.appendRow(["Date", "Time", "Order No", "Customer", "Phone", "Items", "Total", "Note", "Location", "Status", "Payment"]);
      sheet.setFrozenRows(1);
    }

    // 1. คำนวณ Order No. (รีเซ็ตทุกวัน)
    const today = new Date();
    const dateStr = Utilities.formatDate(today, "GMT+7", "yyyy-MM-dd");

    // เก็บค่าตัวนับใน PropertiesService เพื่อความแม่นยำ
    const scriptProperties = PropertiesService.getScriptProperties();
    let lastDate = scriptProperties.getProperty("LAST_ORDER_DATE");
    let count = Number(scriptProperties.getProperty("ORDER_COUNT")) || 0;

    if (lastDate !== dateStr) {
      count = 0; // ขึ้นวันใหม่ รีเซ็ตเป็น 0
      scriptProperties.setProperty("LAST_ORDER_DATE", dateStr);
    }

    count++;
    scriptProperties.setProperty("ORDER_COUNT", count.toString());

    const orderNo = "#" + count.toString().padStart(2, '0'); // แปลงเป็น #01, #02

    // 2. บันทึกข้อมูล
    const timeStr = Utilities.formatDate(today, "GMT+7", "HH:mm:ss");

    // สร้างรายการอาหารเป็น Text
    let itemsStr = data.items.map(i => {
       let txt = `- ${i.name} x${i.quantity}`;
       if (i.selectedOptions) txt += ` (${Object.values(i.selectedOptions).join(',')})`;
       return txt;
    }).join("\n");

    const rowData = [
      dateStr, 
      timeStr, 
      orderNo, 
      data.customerName, 
      "'"+data.customerPhone, // ใส่ ' นำหน้าเพื่อให้เป็น Text
      itemsStr,
      data.total,
      data.note || "-",
      data.locationLink || "-",
      "รอส่ง (Pending)", // Status เริ่มต้น
      "รอตรวจ (Checking)" // Payment เริ่มต้น
    ];

    sheet.appendRow(rowData);

    // จัดรูปแบบ (Data Validation) สำหรับปุ่มสถานะ
    const lastRow = sheet.getLastRow();

    // สร้าง Dropdown สถานะส่งอาหาร
    const statusRule = SpreadsheetApp.newDataValidation().requireValueInList(["รอส่ง (Pending)", "กำลังส่ง (Delivery)", "ส่งแล้ว (Completed)"]).build();
    sheet.getRange(lastRow, 10).setDataValidation(statusRule);

    // สร้าง Dropdown สถานะโอนเงิน
    const payRule = SpreadsheetApp.newDataValidation().requireValueInList(["รอตรวจ (Checking)", "โอนแล้ว (Verified)", "ยกเลิก (Cancelled)"]).build();
    sheet.getRange(lastRow, 11).setDataValidation(payRule);

    return ContentService.createTextOutput(JSON.stringify({ 
      result: "success", 
      orderNo: orderNo 
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ result: "error", error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// ฟังก์ชันป้องกันการแก้ไข (ล็อคเซลล์)
function onEdit(e) {
  const range = e.range;
  const sheet = range.getSheet();

  // ทำงานเฉพาะชีท Orders
  if (sheet.getName() !== SHEET_NAME) return;

  // อนุญาตให้แก้แค่คอลัมน์ J (Status) และ K (Payment) เท่านั้น
  const col = range.getColumn();
  if (col < 10 && !isUnlocked()) { 
    // ถ้าพยายามแก้ข้อมูลลูกค้า (คอลัมน์ 1-9) และยังไม่ได้ปลดล็อค
    e.range.setValue(e.oldValue); // คืนค่าเดิม
    Browser.msgBox("⚠️ Access Denied: ข้อมูลลูกค้าถูกล็อค ต้องใช้รหัสผ่านเพื่อแก้ไข");
  }
}

// ฟังก์ชันปลดล็อคด้วยรหัสผ่าน (สร้างเมนู)
function onOpen() {
  SpreadsheetApp.getUi()
      .createMenu('Admin Controls')
      .addItem('🔓 ปลดล็อคเพื่อแก้ไขข้อมูล (Unlock)', 'unlockSheet')
      .addItem('🔒 ล็อคข้อมูล (Lock)', 'lockSheet')
      .addToUi();
}

function unlockSheet() {
  const ui = SpreadsheetApp.getUi();
  const result = ui.prompt('Security Check', 'กรุณาใส่รหัสผ่าน (Admin Password):', ui.ButtonSet.OK_CANCEL);

  if (result.getSelectedButton() == ui.Button.OK) {
    if (result.getResponseText() === EDIT_PASSWORD) {
      PropertiesService.getUserProperties().setProperty("IS_ADMIN_UNLOCKED", "TRUE");
      ui.alert("✅ ปลดล็อคแล้ว: คุณสามารถแก้ไขข้อมูลได้ชั่วคราว");
    } else {
      ui.alert("❌ รหัสผ่านผิด!");
    }
  }
}

function lockSheet() {
  PropertiesService.getUserProperties().deleteProperty("IS_ADMIN_UNLOCKED");
  SpreadsheetApp.getUi().alert("🔒 ล็อคระบบแล้ว");
}

function isUnlocked() {
  return PropertiesService.getUserProperties().getProperty("IS_ADMIN_UNLOCKED") === "TRUE";
}
```

4.  กด **Save** (ไอคอนแผ่นดิสก์)
5.  กดปุ่ม **Deploy** (สีน้ำเงินมุมขวาบน) > **New deployment**
6.  เลือกประเภทเป็น **Web app**
7.  ตั้งค่าตามนี้:
    *   Description: `SeoulGood Backend`
    *   Execute as: **Me** (อีเมลของคุณ)
    *   Who has access: **Anyone** (สำคัญมาก! เพื่อให้หน้าเว็บส่งข้อมูลได้)
8.  กด **Deploy** และ **Copy URL** ที่ได้ (มันจะขึ้นต้นด้วย `https://script.google.com/macros/s/...`)
9.  นำ URL นี้มาใส่ในไฟล์ `services/orderService.ts` ที่ผมจะสร้างให้ด้านล่าง

---

### ส่วนที่ 2: อัปเดตโค้ดหน้าเว็บ

ผมจะสร้างไฟล์ใหม่ `services/orderService.ts` เพื่อจัดการการส่งข้อมูล และแก้ไข `App.tsx` เพื่อให้เชื่อมต่อกับระบบใหม่นี้ครับ

