      .build();
    sheet.getRange(lastRow, 9).setDataValidation(statusRule);

    // Dropdown: ตรวจเช็คยอดโอน (Column 10)
    const payRule = SpreadsheetApp.newDataValidation()
      .requireValueInList(["รอตรวจ (Checking)", "โอนแล้ว (Verified)", "สลิปปลอม/ไม่มียอด (Invalid)"])
      .build();
    sheet.getRange(lastRow, 10).setDataValidation(payRule);

    return ContentService.createTextOutput(JSON.stringify({ result: "success", orderNo: orderNo })).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ result: "error", error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
