```javascript
// --- ส่วนเสริมสำหรับเมนูพิมพ์ (SeoulGood Manager) ---

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('SeoulGood Manager')
    .addItem('🖨️ เปิดหน้าต่างพิมพ์ (Print Console)', 'showPrintSidebar')
    .addToUi();
}

function showPrintSidebar() {
  var html = HtmlService.createHtmlOutputFromFile('Sidebar')
      .setTitle('ระบบพิมพ์ใบเสร็จ - SeoulGood')
      .setWidth(300);
  SpreadsheetApp.getUi().showSidebar(html);
}

function getSelectedOrderData() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var row = sheet.getActiveCell().getRow();

  if (row < 2) return { error: "กรุณาเลือกแถวที่มีข้อมูลออเดอร์" };

  // --- ปรับ Column ตามรูปภาพที่คุณส่งมา ---
  // A=1, B=2, C=3, D=4, E=5, F=6, G=7

  var date = sheet.getRange(row, 1).getValue();         // Col A: วันที่
  var time = sheet.getRange(row, 2).getValue();         // Col B: เวลา
  var queue = sheet.getRange(row, 3).getValue();        // Col C: ลำดับคิว
  var name = sheet.getRange(row, 4).getValue();         // Col D: ชื่อลูกค้า
  var phone = sheet.getRange(row, 5).getValue();        // Col E: เบอร์โทร
  var itemsRaw = sheet.getRange(row, 6).getValue();     // Col F: รายการอาหาร
  var total = sheet.getRange(row, 7).getValue();        // Col G: ยอดเงิน

  // จัดรูปแบบรายการอาหาร (ตัดเครื่องหมายจุลภาคถ้าจำเป็น)
  var items = [];
  if (itemsRaw) {
    items = String(itemsRaw).split(',').map(function(i) { return i.trim(); });
  }

  return {
    orderId: queue || '-',
    timestamp: (date ? formatDate(date) : '') + ' ' + (time || ''),
    customerName: name,
    customerPhone: phone,
    items: items, 
    total: total,
    note: '' // ในรูปไม่เห็นช่อง Note ถ้ามีให้ใส่เลข Column เพิ่ม
  };
}

// ฟังก์ชันช่วยจัดรูปแบบวันที่
function formatDate(date) {
  if (!date) return '';
  try {
    return Utilities.formatDate(new Date(date), "GMT+7", "dd/MM/yyyy");
  } catch (e) {
    return date;
  }
}
```

