                        <button onClick={sendToLine} className={`w-full text-white py-4 rounded-xl font-bold text-xl shadow-lg transition flex items-center justify-center gap-2 bg-[#06C755] hover:bg-[#05b64d] active:scale-[0.98]`}>
                            <Send size={24} /> ยืนยันการสั่งทาง LINE
                        </button>
                    </div>
                </div>
            )}

            {/* Confirmation Modal */}
            {showConfirmModal && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                    <div className="bg-white rounded-2xl w-full max-w-sm p-5 shadow-2xl relative">
                        <button onClick={() => setShowConfirmModal(false)} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600 p-2"><X size={20} /></button>

                        <div className="text-center mb-4">
                            <h3 className="font-bold text-xl text-gray-800">ขั้นตอนการส่ง (Steps)</h3>
                            <p className="text-xs text-gray-500">กรุณาทำตาม 2 ขั้นตอนง่ายๆ ด้านล่าง</p>
                        </div>
                        {currentOrderId && currentOrderId !== '(Offline)' && (
                            <div className="mb-3 text-center">
                                <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-full text-sm font-bold border border-orange-200">Order ID: {currentOrderId}</span>
                            </div>
                        )}
                        <div className="bg-gray-50 p-3 rounded-lg border border-gray-100 mb-3">
                            <div className="flex items-center gap-2 mb-2">
                                <div className="bg-orange-100 text-orange-600 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold">1</div>
                                <span className="font-bold text-gray-700 text-sm">คัดลอกรูปสลิป (Copy Slip)</span>
                            </div>
                            <div className="flex gap-3">
                                <div className="w-16 h-16 bg-white rounded border border-gray-200 overflow-hidden shrink-0">
                                    <img src={slipPreview || ''} className="w-full h-full object-cover" />
                                </div>
                                <div className="flex-1 flex flex-col gap-1">
                                    <button onClick={handleCopySlip} className={`w-full flex-1 rounded-lg font-bold text-sm transition flex flex-col items-center justify-center gap-1 border ${copyStatus === 'success' ? 'bg-green-100 text-green-700 border-green-200' : 'bg-white border-gray-300 text-gray-700 hover:bg-gray-50 shadow-sm'}`}>
                                        {copyStatus === 'success' ? <><Check size={20} className="text-green-600"/><span>คัดลอกแล้ว!</span></> : <><Copy size={18} className="text-gray-500"/><span>กดปุ่มเพื่อคัดลอก</span></>}
                                    </button>
                                    <span className="text-[10px] text-gray-400 text-center px-1">(หากปุ่มกดไม่ติด ให้กดค้างที่รูปเพื่อคัดลอก)</span>
                                </div>
                            </div>
                        </div>
                        <div className="bg-gray-50 p-3 rounded-lg border border-gray-100 mb-4">
                             <div className="flex items-center gap-2 mb-2">
                                <div className="bg-green-100 text-green-600 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold">2</div>
                                <span className="font-bold text-gray-700 text-sm">ส่งเข้า LINE (Send)</span>
                            </div>
                            <p className="text-xs text-gray-500 ml-8 mb-2">กดปุ่มเปิด LINE แล้วกด <strong className="text-black">วาง (Paste)</strong> รูปในช่องแชท</p>
                        </div>
                        <div className="mb-4 text-xs text-center text-gray-600 bg-orange-50 p-2 rounded border border-orange-100">หลังจากระบบตรวจสอบสลิปการโอน แล้วพนักงานยืนยันการรับยอดโอนของลูกค้า อาหารของท่านรอ 15-20 นาที ทั้งนี้ขึ้นอยู่กับระยะและคิวของลูกค้าท่านอื่นๆ</div>
                        <button onClick={handleOpenLine} disabled={isSavingOrder} className={`w-full text-white py-3 rounded-xl font-bold shadow-lg active:scale-95 transition flex items-center justify-center gap-2 text-lg ${isSavingOrder ? 'bg-gray-400 cursor-not-allowed' : 'bg-[#06C755] hover:bg-[#05b64d]'}`}>
                            {isSavingOrder ? <><Loader2 className="animate-spin" /> กำลังส่งออเดอร์...</> : <><Send size={20} /> เปิด LINE ส่งออเดอร์</>}
                        </button>
                    </div>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { Search, Store, Crosshair } from 'lucide-react';
import { LocationState } from '../types';

// --- Custom Colored Icons ---
// Using leaflet-color-markers hosted on GitHub for reliability
const shadowUrl = 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/0.7.7/images/marker-shadow.png';

const RedIcon = new L.Icon({
  iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png',
  shadowUrl: shadowUrl,
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowSize: [41, 41]
});

const GreenIcon = new L.Icon({
  iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-green.png',
  shadowUrl: shadowUrl,
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowSize: [41, 41]
});

interface MapPickerProps {
  onLocationSelect: (loc: LocationState) => void;
  initialLocation?: LocationState | null;
}

// Convert 16°26'10.5"N 103°30'07.3"E to Decimal
const STORE_LAT = 16.43625;
const STORE_LNG = 103.502028;
const STORE_LOCATION: [number, number] = [STORE_LAT, STORE_LNG];

// Component to handle map movement programmatically
const MapController = ({ center, locateTrigger }: { center: L.LatLngExpression | null, locateTrigger: number }) => {
  const map = useMap();

  // FIX: แก้ไขปัญหาแผนที่โหลดไม่สมบูรณ์ (เป็นสีเทาหรือขาดๆหายๆ) เมื่อแสดงใน Modal
  // เหตุผล: Leaflet คำนวณขนาดผิดตอนที่ Modal กำลังเลื่อนขึ้นมา (Animation)
  // วิธีแก้: สั่งให้คำนวณขนาดใหม่ (invalidateSize) หลังจากเวลาผ่านไปเล็กน้อย
  useEffect(() => {
    const timer = setTimeout(() => {
        map.invalidateSize();
    }, 500); // รอ 0.5 วินาทีเพื่อให้ Modal แสดงผลเสร็จสมบูรณ์
    return () => clearTimeout(timer);
  }, [map]);

  // Handle Search Center
  useEffect(() => {
    if (center) {
      map.flyTo(center, 16);
    }
  }, [center, map]);

  // Handle GPS Locate Trigger
  useEffect(() => {
    if (locateTrigger > 0) {
      map.locate({ setView: true, maxZoom: 16 });
    }
  }, [locateTrigger, map]);

  return null;
};

const LocationMarker: React.FC<{ onSelect: (lat: number, lng: number) => void, position: L.LatLng | null }> = ({ onSelect, position }) => {
  const map = useMapEvents({
    click(e) {
      onSelect(e.latlng.lat, e.latlng.lng);
      map.flyTo(e.latlng, map.getZoom());
    },
    locationfound(e) {
      onSelect(e.latlng.lat, e.latlng.lng);
      map.flyTo(e.latlng, 16);
    },
  });

  // Locate user on first load if no initial position
  useEffect(() => {
    if (!position) {
      map.locate();
    }
  }, [map, position]);

  return position === null ? null : (
    <Marker position={position} icon={GreenIcon}>
       <Popup>จุดส่งอาหาร (Delivery Point)</Popup>
    </Marker>
  );
};

export const MapPicker: React.FC<MapPickerProps> = ({ onLocationSelect, initialLocation }) => {
  const [position, setPosition] = useState<L.LatLng | null>(
    initialLocation ? new L.LatLng(initialLocation.lat, initialLocation.lng) : null
  );

  // Search State
  const [searchText, setSearchText] = useState('');
  const [mapCenter, setMapCenter] = useState<L.LatLngExpression | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [locateTrigger, setLocateTrigger] = useState(0); // Counter to trigger location

  const handleSelect = (lat: number, lng: number) => {
    const newPos = new L.LatLng(lat, lng);
    setPosition(newPos);
    onLocationSelect({ lat, lng, address: `Lat: ${lat.toFixed(4)}, Lng: ${lng.toFixed(4)}` });
  };

  const performSearch = async () => {
    if (!searchText.trim()) return;
    setIsSearching(true);
    try {
        // Use OpenStreetMap Nominatim API for search
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchText)}&limit=1`);
        const data = await response.json();
        if (data && data.length > 0) {
            const lat = parseFloat(data[0].lat);
            const lon = parseFloat(data[0].lon);
            setMapCenter([lat, lon]);
        } else {
            alert('ไม่พบสถานที่ (Location not found)');
        }
    } catch (e) {
        console.error("Search error", e);
        alert('เกิดข้อผิดพลาดในการค้นหา');
    } finally {
        setIsSearching(false);
    }
  };

  const handleLocateMe = () => {
      setLocateTrigger(prev => prev + 1);
  };

  return (
    <div className="h-full w-full rounded-lg overflow-hidden border-2 border-orange-200 shadow-inner z-0 relative flex flex-col bg-gray-100">

      {/* Search Bar Overlay */}
      <div className="absolute top-2 left-2 right-2 z-[500] flex gap-2 p-1.5 bg-white/95 backdrop-blur-sm rounded-lg shadow-md border border-gray-200">
         <div className="relative flex-1">
            <input 
                type="text" 
                placeholder="ค้นหาสถานที่ / Search Location..." 
                className="w-full pl-9 pr-2 py-2 text-sm border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-orange-400 bg-gray-50"
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && performSearch()}
            />
            <Search className="absolute left-2.5 top-2.5 text-gray-400" size={16} />
         </div>
         <button 
            onClick={performSearch}
            className="bg-orange-500 hover:bg-orange-600 text-white px-4 rounded-md transition flex items-center justify-center min-w-[3rem]"
            disabled={isSearching}
         >
            {isSearching ? <span className="animate-spin text-xs">⌛</span> : "ค้นหา"}
         </button>
      </div>

      {/* Locate Me Button */}
      <button
          onClick={handleLocateMe}
          className="absolute bottom-8 right-2 z-[500] bg-white p-2 rounded-full shadow-md border border-gray-300 text-gray-700 hover:text-blue-600 hover:border-blue-500 active:scale-95 transition"
          title="ตำแหน่งปัจจุบัน (Current Location)"
      >
          <Crosshair size={24} />
      </button>

      <MapContainer 
        center={STORE_LOCATION} // Default center to store
        zoom={13} 
        scrollWheelZoom={true} 
        style={{ height: '100%', width: '100%' }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* Controllers */}
        <MapController center={mapCenter} locateTrigger={locateTrigger} />

        {/* User Selection Marker (Green) */}
        <LocationMarker onSelect={handleSelect} position={position} />

        {/* Fixed Store Marker (Red) */}
        <Marker position={STORE_LOCATION} icon={RedIcon}>
           <Popup autoPan={false}>
              <div className="text-center min-w-[120px]">
                 <strong className="text-orange-600 flex items-center gap-1 justify-center mb-1">
                    <Store size={16}/> ร้านอาหารด่วน
                 </strong>
                 <p className="text-xs text-gray-500 m-0">จุดเริ่มต้นส่งอาหาร</p>
                 <p className="text-[10px] text-gray-400 mt-1">{STORE_LAT.toFixed(5)}, {STORE_LNG.toFixed(5)}</p>
              </div>
           </Popup>
        </Marker>
      </MapContainer>

      <div className="absolute bottom-0 left-0 right-0 bg-white/90 text-[10px] text-center text-gray-500 py-1 z-[400] border-t border-gray-200">
        *แตะที่แผนที่ หรือกดปุ่มเป้าหมาย เพื่อปักหมุดจุดส่งอาหาร
      </div>
    </div>
  );
};
